
const ART={akane:'data:image/webp;base64,',aoi:'data:image/webp;base64,',chinatsu:'data:image/webp;base64,',nagi:'data:image/webp;base64,',momoka:'data:image/webp;base64,',milku:'data:image/webp;base64,',reina:'data:image/webp;base64,',concept08:'data:image/webp;base64,',concept09:'data:image/webp;base64,',concept10:'data:image/webp;base64,',concept11:'data:image/webp;base64,',concept12:'data:image/webp;base64,',concept13:'data:image/webp;base64,',concept14:'data:image/webp;base64,',concept15:'data:image/webp;base64,',concept16:'data:image/webp;base64,',concept17:'data:image/webp;base64,'
};
// 0.6.7.3: Two canonical images, one each for Momoka/Milku.
// Keep the four independent unit variants and all save IDs unchanged.
const CANONICAL_ART={momoka:ART.momoka,milku:ART.milku};
function characterArt(personId){return CANONICAL_ART[personId]||ART[personId];}
const COMPACT_PEOPLE=new Set(['momoka','milku']);
function onePortraitPerPerson(units){const seen=new Set();return units.filter(u=>!COMPACT_PEOPLE.has(u.person)||(!seen.has(u.person)&&seen.add(u.person)));}
function compactVariantRows(personId,visibleUnits,showStatus=true){
  return `<div class="compact-variants" aria-label="${PEOPLE[personId].name}のバージョン一覧">${visibleUnits.map(u=>{const d=data(u.id);return `<button type="button" class="compact-variant-button" onclick="openUnit('${u.id}')" aria-label="${PEOPLE[personId].name} ${u.title} の詳細を開く"><span class="compact-rarity">${u.rarity}</span><span class="compact-variant-name">${u.title}</span><span class="compact-role">${ROLES[u.role].name}</span>${showStatus?`<small>${d?'Lv.'+d.lv:'未所持'}</small>`:''}<span aria-hidden="true">›</span></button>`}).join('')}</div>`;
}


// Ver.0.9.3.0: expression portrait registry.
// Add heroine expression images here without touching the original ART data.
// Example: ART_EXPRESSIONS.momoka.smile = "data:image/webp;base64,..." or a relative/absolute image URL.
const EXPRESSION_FACES=Object.freeze(['normal','smile','blush','pout','sad','surprise']);
const ART_EXPRESSIONS={
  momoka:{normal:'',smile:'',blush:'',pout:'',sad:''},
  milku:{normal:'',smile:'',blush:'',pout:'',sad:''}
};
function normalizeExpressionFace(face){return EXPRESSION_FACES.includes(face)?face:'normal';}
function expressionArt(personId,face='normal'){
  const key=normalizeExpressionFace(face), table=ART_EXPRESSIONS[personId]||{};
  return table[key]||table.normal||characterArt(personId);
}
function hasExpressionArt(personId,face='normal'){
  const key=normalizeExpressionFace(face), table=ART_EXPRESSIONS[personId]||{}, src=table[key]||table.normal||'';
  return !!src && src!==characterArt(personId);
}
